import json
from abc import ABC, abstractmethod

class JSONHandler(ABC):
    _registry = {}

    @abstractmethod
    def from_json(self, data):
        pass

    @classmethod
    def register_factory(cls, id_, factory):
        cls._registry[id_] = factory

    @classmethod
    def get_instance_by_id(cls, id_):
        return cls._registry.get(id_)()

class JSONSerializable(JSONHandler):
    def to_json(self):
        raise NotImplementedError('Subclasses must implement this method')

class JSONFactory:
    @abstractmethod
    def from_json(self, data):
        pass

def register_factory(cls):
    for attr_name in dir(cls):
        if hasattr(getattr(cls, attr_name), 'from_json'):
            id_ = attr_name.lower()
            JSONHandler.register_factory(id_, getattr(cls, attr_name))
