import argparse
import sys

def get_word_count(filename):
    try:
        with open(filename, 'r') as f:
            return len(f.read().split())
    except FileNotFoundError:
        print(""File not found."")
        sys.exit(1)
    except Exception as e:
        print(f""An error occurred: {e}"")
        sys.exit(2)

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description='Word count script')
    parser.add_argument('-v', '--verbose', action='store_true', help='Print verbose output')
    parser.add_argument('-f', '--filename', type=str, required=False, help='File name to process')
    args = parser.parse_args()

    if not args.filename:
        parser.print_help()
        sys.exit()

    word_count = get_word_count(args.filename)

    if args.verbose:
        print(f""The file {args.filename} contains {word_count} words."")
