import random
import string
import hashlib
from datetime import datetime, timedelta

class SensorData:
    def __init__(self, temperature, humidity, timestamp, metadata):
        self.temperature = self._validate_temperature(temperature)
        self.humidity = self._validate_humidity(humidity)
        self.timestamp = self._generate_timestamp(timestamp)
        self.metadata = metadata

    @staticmethod
    def _validate_temperature(temp):
        if temp < -273.15 or temp > 100:
            raise ValueError(""Temperature must be between -273.15°C and 100°C"")
        return temp

    @staticmethod
    def _validate_humidity(hum):
        if hum < 0 or hum > 100:
            raise ValueError(""Humidity must be between 0% and 100%"")
        return hum

    @staticmethod
    def _generate_timestamp(timestamp):
        if not timestamp:
            now = datetime.now()
            days_ago = random.randint(0, 6) * 86400 # Generate timestamps from last 7 days
            offset_time = now - timedelta(seconds=days_ago)
            formatted_date_time = offset_time.strftime(""%Y-%m-%d %H:%M:%S"")
            return formatted_date_time
        return timestamp

def generate_sensor_data(num_sensors, start_timestamp=None):
    sensor_data_list = []
    for _ in range(num_sensors):
        temperature = round(random.uniform(-273.15, 100), 2)
        humidity = random.randint(0, 100)
        timestamp = SensorData._generate_timestamp(start_timestamp)
        metadata = f""Generated on {datetime.now().strftime('%Y-%m-%d %H:%M:%S')} by {random.choice(['Computer1', 'Computer2'])}""

        try:
            sensor_data_list.append(SensorData(temperature, humidity, timestamp, metadata))
        except ValueError as e:
            print(f""Error: {e}"")

    return sensor_data_list

def main():
    num_sensors = 5
    start_timestamp = None
    sensor_data = generate_sensor_data(num_sensors, start_timestamp)
    for data in sensor_data:
        print(data.temperature, data.humidity, data.timestamp, data.metadata)

if __name__ == ""__main__"":
    main()
