from flask import Flask, request, jsonify
app = Flask(__name__)

# List of existing resources (simulated database)
resources = [
    {""id"": 1, ""name"": ""Resource 1"", ""description"": ""This is a description""},
    {""id"": 2, ""name"": ""Resource 2"", ""description"": ""Another one""}
]

@app.route('/resources/<int:resource_id>', methods=['PATCH'])
def update_resource(resource_id):
    if not any(resource['id'] == resource_id for resource in resources):
        return jsonify({""error"": ""Resource not found""}), 404

    request_data = request.get_json()
    for key, value in request_data.items():
        if key in ['name', 'description']:
            if key == 'name':
                resource_index = next((i for i, r in enumerate(resources) if r['id'] == resource_id), None)
                resources[resource_index]['name'] = value
            elif key == 'description':
                resources[resource_id-1]['description'] = value

    return jsonify({""message"": ""Resource updated successfully""}), 200

@app.route('/resources/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    if not any(resource['id'] == resource_id for resource in resources):
        return jsonify({""error"": ""Resource not found""}), 404

    global resources
    resources = [r for r in resources if r['id'] != resource_id]

    return jsonify({""message"": ""Resource deleted successfully""}), 200

if __name__ == '__main__':
    app.run(debug=True)
