        self.value = 0
        self.next = None


def create_node(value):
    node = Node()
    node.value = value
    return node


def print_list(head):
    temp = head
    while temp is not None:
        print(temp.value, end="" "")
        temp = temp.next
    print()


def main():
    # Load the C++ library using ctypes
    lib = CDLL('./libcpp.so')

    # Define Python data types to be passed as arguments
    c_int_ptr = POINTER(c_int)
    c_char_p = c_char_p

    # Define Python functions that call C++ functions
    def add_numbers(a, b):
        c_func = lib.add_numbers
        c_func.argtypes = [c_int, c_int]
        c_func.restype = c_int
        return c_func(a, b)

    def print_string(s):
        c_func = lib.print_string
        c_func.argtypes = [c_char_p]
        c_func.restype = None
        c_func(s.encode())

