        s = ""Hello, World!""
        print_string(s)

    except Exception as e:
        # Handle errors and exceptions from the C++ library
        print(f""Error: {e}"")
        if lib is not None:
            lib.free()
    else:
        if lib is not None:
            lib.deallocate()


