import json

class Registry:
    def __init__(self):
        self.functions = {}

    def add_function(self, id, function):
        if id not in self.functions:
            self.functions[id] = function

    def get_function(self, id):
        return self.functions.get(id)

class JSONHandler:
    def __init__(self, registry):
        self.registry = registry

    def convert_to_json(self, data):
        return json.dumps(data)

    def construct_instance_from_json(self, json_string):
        data = json.loads(json_string)
        factory_function = self.registry.get_function(data['factory_id'])
        if factory_function is None:
            raise ValueError(""Factory function not found"")
        return factory_function(data)

class BaseClass(json.JSONEncoder):
