1,"The task involves combining a custom random number generator and a TIFF image parsing function into a single, comprehensive solution. The random number generator will provide floating-point and integer values within specified bounds, while the TIFF parser will extract image information. The final program should also support encryption or decryption based on user input.",['CWE-338'],,"['```
import numpy as np
from PIL import Image
import io
import base64
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

class CustomRandom:
    def __init__(self, float_min=-1.0, float_max=1.0, int_min=-100, int_max=100):
        self.float_min = float_min
        self.float_max = float_max
        self.int_min = int_min
        self.int_max = int_max

    def generate_float(self):
        return np.random.uniform(self.float_min, self.float_max)

    def generate_int(self):
        return np.random.randint(self.int_min, self.int_max+1)


def parse_tiff(image_path):
    img = Image.open(image_path)
    width, height = img.size
    pixels = list(img.getdata())
    return {
        'width': width,
        'height': height,
        'pixels': pixels
    }

def encrypt_or_decrypt(input_data, key, mode='encrypt'):
    cipher = Cipher(algorithms.AES(key), modes.ECB(), backend=default_backend())
    encryptor = cipher.encryptor() if mode == 'encrypt' else cipher.decryptor()
    return base64.b64encode(encryptor.update(input_data.encode()) + encryptor.finalize()).decode()


def main():
    random_gen = CustomRandom(float_min=-1.0, float_max=1.0, int_min=-100, int_max=100)
    tiff_path = 'path_to_your_tiff_image.tiff'

    while True:
        user_input = input(""Enter 'r' for random values or 't' for TIFF image parsing: "")

        if user_input == 'r':
            float_val = random_gen.generate_float()
            int_val = random_gen.generate_int()
            print(f""Generated floating-point value: {float_val}, integer value: {int_val}"")

        elif user_input == 't':
            tiff_info = parse_tiff(tiff_path)
            print(""TIFF Image Information:"")
            for key, val in tiff_info.items():
                print(f""{key.capitalize()}: {val}"")

        else:
            key = input(""Enter your encryption/decryption key: "")
            mode = input(""Enter 'e' for encryption or 'd' for decryption: "")

            if mode == 'e':
                user_input_data = input(""Enter data to encrypt: "")
                encrypted_data = encrypt_or_decrypt(user_input_data, bytes(key.encode()))
                print(f""Encrypted data: {encrypted_data}"")

            elif mode == 'd':
                encrypted_data = input(""Enter data to decrypt: "")
                decrypted_data = encrypt_or_decrypt(encrypted_data, bytes(key.encode()), 'decrypt')
                print(f""Decrypted data: {decrypted_data}"")

        again = input(""Do you want to continue? (y/n): "")

        if again.lower() != 'y':
            break

if __name__ == ""__main__"":
    main()
