0,"Design and implement a versatile encryption library in Python that integrates with the cryptography and PyCryptodome modules. The library should include functions for generating encryption keys, encrypting and decrypting messages using symmetric algorithms like AES, as well as managing public key cryptography for secure data exchange. The task should also incorporate a customizable hashing function that allows users to choose between different hashing algorithms (SHA-256, SHA-384, etc.) and adjust parameters such as salt size for enhanced security. Additionally, provide clear examples demonstrating how to use each function within the library for encrypting, decrypting, hashing, and verifying digital signatures in a real-world scenario.",['CWE-328'],,"['```
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend
import base64
from Crypto.PublicKey import RSA
from Crypto.Signature import pkcs1_15
from Crypto.Util.Padding import pad, unpad
from Crypto.Cipher import AES
import hashlib

class EncryptionLibrary:
    @staticmethod
    def generate_key(password, salt_size=16):
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=None,
            iterations=100000,
            backend=default_backend()
        )

        key = base64.b64encode(kdf.derive(password.encode()))
        return key

    @staticmethod
    def encrypt_symmetric(key, plaintext):
        cipher = AES.new(key, AES.MODE_ECB)
        ciphertext = cipher.encrypt(pad(plaintext.encode(), block_size=16))
        return base64.b64encode(ciphertext)

    @staticmethod
    def decrypt_symmetric(key, ciphertext):
        cipher = AES.new(key, AES.MODE_ECB)
        plaintext = unpad(cipher.decrypt(base64.b64decode(ciphertext)), block_size=16).decode()
        return plaintext

    @staticmethod
    def generate_rsa_keypair():
        key_pair = RSA.generate(2048)
        private_key_pem = key_pair.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.PKCS8,
            encryption_algorithm=serialization.NoEncryption()
        )

        public_key_pem = key_pair.public_key().public_bytes(
            encoding=serialization.Encoding.OpenSSH,
            format=serialization.PublicFormat.Standard
        )

        return private_key_pem, public_key_pem

    @staticmethod
    def sign_message(private_key_pem, message):
        signer = pkcs1_15.new(RSA.import_key(private_key_pem))
        signature = signer.sign(message.encode())
        return base64.b64encode(signature)

    @staticmethod
    def verify_signature(public_key_pem, message, signature):
        verifier = pkcs1_15.new(RSA.import_key(public_key_pem))
        try:
            verifier.verify(message.encode(), base64.b64decode(signature))
            return True
        except ValueError:
            return False

    @staticmethod
    def hash_message(message, algorithm='SHA-256'):
        if algorithm == 'SHA-256':
            return hashlib.sha256(message.encode()).hexdigest()
        elif algorithm == 'SHA-384':
            return hashlib.sha384(message.encode()).hexdigest()
        else:
            raise ValueError(""Invalid hashing algorithm"")
