def CryptoFileMetadata(filePath):
    try:
        # Compute MD5 checksum and extract metadata
        md5 = hashlib.md5(open(filePath, 'rb').read()).hexdigest()
        meta = {
            ""size"": os.path.getsize(filePath),
            ""name"": os.path.basename(filePath),
            ""lastModifiedTime"": os.path.getmtime(filePath)
        }

        # Initialize array of cryptographic functions
        cryptoFuncs = []
        if ctypes.CDLL(""libcrypto"").func_sha256:
            cryptoFuncs.append(CryptoFuncStruct(""SHA-256"", ctypes.CDLL(""libcrypto"").func_sha256))
        if ctypes.CDLL(""libcrypto"").func_sha384:
            cryptoFuncs.append(CryptoFuncStruct(""SHA-384"", ctypes.CDLL(""libcrypto"").func_sha384))
        if ctypes.CDLL(""libcrypto"").func_sha512:
            cryptoFuncs.append(CryptoFuncStruct(""SHA-512"", ctypes.CDLL(""libcrypto"").func_sha512))

        # Execute MD5 checksum and cryptographic functions
        print(f""File Information: {meta['name']}, Size: {meta['size']} bytes, Last Modified: {meta['lastModifiedTime']}"")
        for func in cryptoFuncs:
            try:
                result = func.address(filePath)
                print(f""{func.name} Hash: {result.hex()}"")
            except Exception as e:
                print(f""Error executing {func.name}: {str(e)}"")
    except FileNotFoundError:
        print(f""File not found: {filePath}"")
