class DeviceInformation:
    def __init__(self, device_id=None, location=None, description=None):
        self.device_id = device_id if device_id else generate_device_id()
        self.location = location if location else Location(random.uniform(0, 90), random.uniform(0, 180))
        self.description = description if description else DeviceDescription()

def generate_device_id(seed):
    random.seed(seed)
