def calculate_crc(file_path):
    crc = hashlib.md5(open(file_path, 'rb').read()).hexdigest()
    return {""crc_flag"": 1, ""md5_hash"": bytes.fromhex(crc), ""file_size"": os.path.getsize(file_path)}

