import os
import hashlib
from datetime import datetime

class ProjectFile:
    def __init__(self, project_name):
        self.project_name = project_name
        self.file_names = []
        self.versions = []
        self.sizes = []
        self.checksums = []
        self.modification_timestamps = []
        self.notes = []

    def add_file(self, file_name, version, size):
        self.file_names.append(file_name)
        self.versions.append(version)
        self.sizes.append(size)

    def calculate_checksum(self, file_name):
        with open(file_name, 'rb') as f:
            data = f.read()
        checksum = hashlib.sha256(data).hexdigest()
        return checksum

    def update_file_info(self, file_name):
        size = os.path.getsize(file_name)
        modification_timestamp = datetime.fromtimestamp(os.path.getmtime(file_name)).timestamp()
        self.sizes.append(size)
        self.modification_timestamps.append(modification_timestamp)

class VersionControlSystem:
    def __init__(self):
        self.projects = {}

    def create_project(self, project_name):
        if project_name not in self.projects:
            self.projects[project_name] = ProjectFile(project_name)
            print(f""Project '{project_name}' created successfully."")
        else:
            print(""A project with the same name already exists."")

    def add_file_to_project(self, project_name, file_name, version):
        if project_name in self.projects:
            project = self.projects[project_name]
            project.add_file(file_name, version, os.path.getsize(file_name))
            print(f""File '{file_name}' added to project '{project_name}' with version {version}."")
        else:
            print(""Project not found."")

    def calculate_checksum(self, project_name, file_name):
        if project_name in self.projects:
            project = self.projects[project_name]
            checksum = project.calculate_checksum(file_name)
            return checksum
        else:
            print(""Project not found."")

    def update_file_info(self, project_name, file_name):
        if project_name in self.projects:
            project = self.projects[project_name]
            project.update_file_info(file_name)
            print(f""File '{file_name}' updated successfully."")
        else:
            print(""Project not found."")

class FileDownloaderUploader:
    def __init__(self, version_control_system):
        self.version_control_system = version_control_system

    def download_file(self, project_name, file_name):
        if project_name in self.version_control_system.projects:
            project = self.version_control_system.projects[project_name]
            file_path = f""{project_name}/{file_name}""
            print(f""Downloading file '{file_name}' from project '{project_name}' to {file_path}."")
        else:
            print(""Project not found."")

    def upload_file(self, project_name, file_name):
        if project_name in self.version_control_system.projects:
            project = self.version_control_system.projects[project_name]
            file_path = f""{project_name}/{file_name}""
            print(f""Uploading file '{file_name}' to project '{project_name}'."")
        else:
            print(""Project not found."")

# Example usage
