class TransactionAnalyzer:
    def __init__(self, historical_data):
        self.historical_data = historical_data
        self.thresholds = {'amount': [0.5, 2.0], 'time': [(datetime.now().replace(hour=9) - timedelta(hours=1)).strftime('%Y-%m-%d'), (datetime.now() + timedelta(days=7)).strftime('%Y-%m-%d')]}
        self.anomalies = []

    def analyze_transaction(self, transaction):
        if not self.historical_data.get(transaction['user_id'], {}).get('average_spending', 0.0) <= transaction['amount'] <= self.thresholds['amount'][1] and \
           (datetime.strptime(transaction['date'], '%Y-%m-%d') >= self.thresholds['time'][0] and datetime.strptime(transaction['date'], '%Y-%m-%d') <= self.thresholds['time'][1]):
            return False
        else:
            if transaction['amount'] > 2.5 * self.historical_data.get(transaction['user_id'], {}).get('average_spending', 0.0):
                self.anomalies.append({
                    'transaction': transaction,
                    'type': 'excessive_spending'
                })
            return True

