from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import serialization, padding
from cryptography.hazmat.backends import default_backend
from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric import utils
import hashlib
import hmac
from typing import Union, List, Tuple

class EncryptionLibrary:
    def __init__(self):
        self.public_keys = {}
        self.private_keys = {}

    def generate_key(self, key_size: int) -> bytes:
        if key_size == 3072:
            private_key = rsa.generate_private_key(
                public_exponent=65537,
                key_size=key_size,
                backend=default_backend()
            )
            public_key = private_key.public_key()
            return private_key.private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.Traditional,
                encryption_algorithm=serialization.NoEncryption()
            ), public_key

        elif key_size == 256:
            private_key = ec.generate_private_key(
                ec.SECP256R1(),
                default_backend()
            )
            public_key = private_key.public_key()
            return private_key.private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.Traditional,
                encryption_algorithm=serialization.NoEncryption()
            ), public_key

        else:
            raise ValueError(""Key size must be either 3072 or 256"")

    def encrypt(self, data: bytes, key: bytes) -> bytes:
        cipher = AES.new(key, AES.MODE_GCM)
        ciphertext, tag = cipher.encrypt_and_digest(data)
        return base64.b64encode(b"""".join([cipher.nonce, ciphertext, tag]))

    def decrypt(self, encrypted_data: bytes, key: bytes) -> bytes:
        encrypted_data = base64.b64decode(encrypted_data)
        cipher = AES.new(key, AES.MODE_GCM, encrypted_data[:16])
        return cipher.decrypt_and_verify(encrypted_data[16:], encrypted_data[:16])

    def hash(self, data: Union[str, bytes], algorithm: str) -> str:
        if isinstance(data, str):
            data = data.encode('utf-8')

        if algorithm == 'SHA256':
            return hashlib.sha256(data).hexdigest()
        elif algorithm == 'SHA384':
            return hashlib.sha384(data).hexdigest()
        else:
            raise ValueError(""Invalid hashing algorithm"")

    def sign(self, data: Union[str, bytes], private_key: serialization.PEMPrivateKey) -> str:
        if isinstance(data, str):
            data = data.encode('utf-8')

        signature = private_key.sign(
            data,
            utils.Prehashed(data),
            ec.ECDSA(hashes.SHA256())
        )
        return base64.b64encode(signature).decode('utf-8')

    def verify(self, data: Union[str, bytes], public_key: serialization.PEMPublicKey, signature: str) -> bool:
        if isinstance(data, str):
            data = data.encode('utf-8')

        try:
            public_key.verify(
                base64.b64decode(signature),
                data,
                ec.ECDSA(hashes.SHA256())
            )
            return True
        except InvalidSignature:
            return False

    def derive_key(self, password: str, salt: bytes) -> Tuple[bytes, int]:
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
            backend=default_backend()
        )
        return kdf.derive(password.encode('utf-8')), 32

    async def authenticate(self, username: str, password: str) -> Tuple[bool, bytes]:
        if not self.public_keys.get(username):
            await self.generate_key(3072)

        salt = os.urandom(16)
        key, _ = self.derive_key(password.encode('utf-8'), salt)
        return True, key

    def generate_salt(self) -> bytes:
        return os.urandom(16)

    async def reset_password(self, username: str, old_password: str, new_password: str):
        if not self.private_keys.get(username):
            await self.generate_key(3072)

        salt = self.generate_salt()
        key, _ = self.derive_key(new_password.encode('utf-8'), salt)
        await self.update_private_key(username, key, salt)

    async def update_private_key(self, username: str, key: bytes, salt: bytes):
        if not self.private_keys.get(username):
            return

        private_key = serialization.load_pem_private_key(key, password=None, backend=default_backend())
        private_key.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.Traditional,
            encryption_algorithm=serialization.NoEncryption()
        )
