from paho.mqtt.client import MQTTMessage

def generate_mqtt_messages(num_messages: int) -> list:
    mqtt_messages = []
    for _ in range(num_messages):
        topic = f""topic-{random.randint(1, 100)}""
        payload = f""{random.getrandbits(256):x}""
        qos = random.choice([0, 1, 2])
        retained = bool(random.randint(0, 1))

        try:
            mqtt_message = MQTTMessage(topic, payload.encode(), qos, retained)
        except Exception as e:
            print(f""Error generating MQTT message: {e}"")
            continue

        mqtt_messages.append({
            ""topic"": topic,
            ""payload"": payload,
            ""qos"": qos,
            ""retained"": retained
        })

    return mqtt_messages

def serialize_mqtt_messages(mqtt_messages: list, filename: str) -> None:
    with open(filename, 'w') as f:
        json.dump([message for message in mqtt_messages], f)

def main():
    try:
        num_messages = int(input(""Enter the number of MQTT messages to generate: ""))
        if num_messages <= 0:
            print(""Invalid input. Please enter a positive integer."")
            return

        mqtt_messages = generate_mqtt_messages(num_messages)

        if len(mqtt_messages) == num_messages:
            serialize_option = input(""Do you want to serialize the MQTT messages into a JSON file? (y/n): "")
            if serialize_option.lower() == 'y':
                filename = input(""Enter the filename for serialization: "")
                serialize_mqtt_messages(mqtt_messages, filename)
        else:
            print(f""Error generating {num_messages} MQTT messages."")
    except ValueError as e:
        print(f""Invalid input. Please enter an integer: {e}"")

if __name__ == ""__main__"":
