def insert_key_after_match(dictionary: dict, search_key: str, insert_key: str, nested_keys: bool = False,
                           case_sensitive: bool = True,
                           verbose_mode: bool = False) -> None:
    if not isinstance(dictionary, dict):
        raise ValueError(""Input is not a dictionary."")
    if not isinstance(search_key, str) or not isinstance(insert_key, str):
        raise ValueError(""Key arguments must be strings."")

    if nested_keys and any(not isinstance(value, dict) for value in dictionary.values()):
        raise ValueError(""Nested keys require dictionaries with the same structure."")

    if case_sensitive:
        search_key = search_key.lower()
        insert_key = insert_key.lower()

    def recursive_search(d):
        for key, value in d.items():
            if (case_sensitive or key.lower() == search_key) and (key not in dictionary or key != search_key):
                if verbose_mode:
                    print(f""Matched '{key}' - inserting '{insert_key}' after it."")
                dictionary.move(key, insert_key)
                return
            if isinstance(value, dict):
                recursive_search(value)

    recursive_search(dictionary)

def move(key, new_key):
