from flask import Flask, request, jsonify
app = Flask(__name__)

# Sample resources dictionary
resources = {
    1: {""name"": ""Resource 1"", ""description"": ""This is a sample resource""},
    2: {""name"": ""Resource 2"", ""description"": ""Another sample resource""}
}

@app.route('/resources/<int:resource_id>', methods=['PATCH'])
def update_resource(resource_id):
    if resource_id in resources:
        updated_fields = request.get_json()
        for field, value in updated_fields.items():
            resources[resource_id][field] = value
        return jsonify(resources[resource_id]), 200
