import argparse
import json
import logging

class Config:
    def __init__(self):
        self.data = {}

    def add_resource(self, name, value):
        self.data[name] = value

    def get_resource(self, name):
        return self.data.get(name)

class ResourceLoader:
    def __init__(self, config_file_path):
        self.config_file_path = config_file_path
        self.config = Config()

    def load_resources(self):
        try:
            with open(self.config_file_path, 'r') as file:
                data = json.load(file)
                for resource_name, value in data.items():
                    self.config.add_resource(resource_name, value)
        except FileNotFoundError:
            logging.warning(f""Configuration file '{self.config_file_path}' not found."")
        except json.JSONDecodeError as e:
            logging.error(f""Error parsing JSON: {e}"")

def main():
    parser = argparse.ArgumentParser(description='Load resources from a configuration file.')
    parser.add_argument('config_file_path', help='Path to the configuration file.')
    args = parser.parse_args()

    resource_loader = ResourceLoader(args.config_file_path)
    resource_loader.load_resources()

    if len(resource_loader.config.data) == 0:
        logging.warning(""No resources loaded."")
    else:
        for resource_name, value in resource_loader.config.data.items():
            print(f""Loaded {resource_name}: {value}"")

if __name__ == ""__main__"":
    logging.basicConfig(level=logging.WARNING)
    main()
