            raise TypeError(""Investment value must be a number"")

def send_alerts(portfolio):
    current_portfolio_value = calculate_portfolio_value(portfolio)
    previous_portfolio_value = portfolio[0].value  # assuming portfolio has at least one investment
    if abs(current_portfolio_value - previous_portfolio_value) > 10000:  # arbitrary threshold for significant change
        print(f""Portfolio value changed significantly from {previous_portfolio_value} to {current_portfolio_value}"")

def update_portfolio(portfolio):
    for investment in portfolio:
        investment.value += (investment.value * 0.01)  # example of updating portfolio value

