class TransactionManager:
    def __init__(self):
        self.transactions = []

    def add_transaction(self, user, amount):
        if amount < 0:
            raise ValueError(""Transaction amount cannot be negative"")
        transaction = {""id"": len(self.transactions), ""status"": ""pending"", ""amount"": amount, ""user"": user}
        self.transactions.append(transaction)

    def update_status(self, transaction_id, new_status):
        for transaction in self.transactions:
            if transaction[""id""] == transaction_id:
                if new_status not in [""approved"", ""declined""]:
                    raise ValueError(""Invalid status"")
                if new_status == ""approved"" and transaction[""status""] != ""pending"":
                    raise ValueError(""Transaction is already approved or declined"")
                transaction[""status""] = new_status
                break

    def get_stats(self):
        total_transactions = len(self.transactions)
        approved_transactions = sum(1 for transaction in self.transactions if transaction[""status""] == ""approved"")
        declined_transactions = sum(1 for transaction in self.transactions if transaction[""status""] == ""declined"")
        return {""total"": total_transactions, ""approved"": approved_transactions, ""declined"": declined_transactions}
