def random_float_cooldown_with_frequency(lower_bound, upper_bound, cooldown_seconds=300, frequency=1):
    check_boundaries(lower_bound, upper_bound)

    def generate_random_number():
        return random.uniform(lower_bound, upper_bound)

    def cooldown_checker():
