            if time.time() - last_generation_time >= cooldown_seconds:
                global frequency
                frequency -= 1
                if frequency > 0:
                    print(f""Generated number: {generate_random_number()}"")
                    last_generation_time = time.time()
                else:
                    print(""Cooldown period in progress. Please wait."")
            else:
                print(""Waiting for cooldown period..."")
            time.sleep(cooldown_seconds)

    global last_generation_time
    last_generation_time = time.time()
    global frequency_counter
    frequency_counter = frequency

    thread = threading.Thread(target=cooldown_checker)
    thread.start()

