func (n *Node) Start() {
	fmt.Printf(""Starting node %d: %s\n"", n.id, n.name)
	// Initialize Redis connection
	client := redis.NewClient(&redis.Options{Addr: n.redisUrl})
	err := client.Ping().Err()
	if err != nil {
		log.Fatal(err)
	}
	defer client.Close()

	// Start thread for handling concurrent operations
	go func() {
		for {
			// Handle incoming requests
			conn, err := n.listenForConnections()
			if err != nil {
				log.Println(err)
			} else {
				go n.handleRequest(conn)
			}
		}
	}()

	// Start logging mechanism
	go func() {
		for {
			// Write log entries to file
			f, err := os.OpenFile(""node-"" + fmt.Sprintf(""%d.log"", n.id), os.O_CREATE|os.O_RDWR|os.O_APPEND, 0666)
			if err != nil {
				log.Println(err)
			} else {
				defer f.Close()
				fmt.Fprintf(f, ""%s: Started node %d: %s\n"", time.Now().Format(time.RFC3339), n.id, n.name)
			}
		}
	}()
}

