    ]

    print(f""Hashing {target_file} using different configurations:"")

    for test in tests:
        result = hash_file_sha256(target_file, **test)

        if 'result' in locals():
            print(f""Result comparison - {result == result}"")

        result = hash_file_sha256(target_file)

        print(result)

def test_hash_function():

    files_to_test = [
