        (""largefile.dat"", {""chunk_size"": 1048576}),
        (""encrypted.bin"", {""salt"": ""mysecretkey""})

    for file, test in files_to_test:
        print(f""Testing {file} with configuration: {test}"")
        result = hash_file_sha256(file, **test)
        if 'result' in locals():
            print(f""Result comparison - {result == result}"")
        print(result)

