import random
from xml.etree import ElementTree as ET
import uuid

class Node:
    def __init__(self):
        self.id = str(uuid.uuid4())
        self.text = None
        self.children = []

def generate_tree(height=5, max_nodes=10):
    if height == 0 or random.randint(1, max_nodes) > 3:
        return None

    node = Node()

    if height > 1:
        for _ in range(random.randint(1, 3)):
            child = generate_tree(height-1)
            if child is not None:
                node.children.append(child)

    return node

def xml_string(node):
    root = ET.Element(""root"")
    tree = xml_node(root, node)

    return ET.tostring(tree, encoding='unicode')

def xml_node(parent, node):
    if node is None:
        return

    element = ET.SubElement(parent, ""node"", {""id"": node.id})

    if node.text is not None:
        ET.SubElement(element, ""text"").text = node.text

    for child in node.children:
        xml_node(element, child)

def validate_xml(xml_string):
    try:
        ET.fromstring(xml_string)
    except ET.ParseError as e:
        return False
    else:
        return True

def save_to_file(xml_string, filename='output.xml'):
    with open(filename, 'w') as f:
        f.write(xml_string)

# Generate tree
