            for command in commands:
                pattern = re.compile(command)
                content[:] = pattern.sub(lambda x: x.group(0).replace(x.group(), placeholders[x.group().split(""/"")[0]]), """".join(content))

            print(""Config file modified successfully."")

        except Exception as e:
            print(f""An error occurred: {e}"")
