def insert_key_after_match(dictionary: dict, search_key: str, insert_key: str, nested_keys: bool = False,
                           case_sensitive: bool = True,
                           verbose_mode: bool = False) -> None:
    if not isinstance(dictionary, dict):
        raise ValueError(""Input must be a dictionary"")

    def recursive_search(d, key):
        for k, v in list(d.items()):
            if (not case_sensitive and key.casefold() == k.casefold()) or (case_sensitive and key == k):
                if verbose_mode:
                    print(f""Match found: {k} -> {v}"")
                d.move_to_end(k)
                d.insert_after(k, insert_key)
                return
            elif isinstance(v, dict) and nested_keys:
                recursive_search(v, key)
        if not any((not case_sensitive and key.casefold() == k.casefold()) or (case_sensitive and key == k) for k in d):
            if verbose_mode:
                print(""No match found"")
            d.move_to_end(key)

    recursive_search(dictionary, search_key)

# Test scenarios
my_dict = {'apple': 5, 'banana': 7}
insert_key_after_match(my_dict, 'banana', 'cherry')
print(my_dict)  # Output: {'apple': 5, 'banana': 7, 'cherry': None}

nested_dict = {'fruits': {'apple': 5, 'banana': 7}, 'vegetables': {'carrot': 2}}
insert_key_after_match(nested_dict['fruits'], 'banana', 'cherry')
print(nested_dict)
