from flask import Flask, request, jsonify
app = Flask(__name__)

# sample resources dictionary
resources = {
    1: {'id': 1, 'name': 'Resource 1', 'description': 'This is Resource 1'},
    2: {'id': 2, 'name': 'Resource 2', 'description': 'This is Resource 2'}
}

# update resource function
@app.route('/resources/<int:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if resource_id not in resources:
        return jsonify({'error': 'Resource not found'}), 404

    updated_data = request.get_json()
    resources[resource_id]['name'] = updated_data.get('name', resources[resource_id]['name'])
    resources[resource_id]['description'] = updated_data.get('description', resources[resource_id]['description'])

    return jsonify(resources[resource_id]), 200

# delete resource function
@app.route('/resources/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    if resource_id not in resources:
        return jsonify({'error': 'Resource not found'}), 404

    default_resource = {'id': resource_id, 'name': '', 'description': ''}
    resources[resource_id] = default_resource

    return jsonify(default_resource), 200

if __name__ == '__main__':
    app.run(debug=True)
