import psycopg2
import logging
import time
import random

class DatabaseExecutor:
    def executeDatabaseQuery(self, sql_query: str, db_params: dict, transaction_status_handler):
        connection = None
        try:
            connection = psycopg2.connect(**db_params)
            cursor = connection.cursor()
            try:
                cursor.execute(sql_query)
                if ""commit"" in transaction_status_handler:
                    connection.commit()
                elif ""rollback"" in transaction_status_handler:
                    connection.rollback()
                else:
                    raise ValueError(""Invalid transaction status handler"")
            except psycopg2.Error as e:
                if ""current transaction is 'invalid'"" in str(e):
                    raise DatabaseTransactionError(""Current transaction is invalid"", e)
                elif ""could not access file"" in str(e) or ""permission denied"" in str(e):
                    raise DatabasePermissionDeniedError(""Database permission denied"", e)
                else:
                    raise DatabaseQueryExecutionError(""Database query execution error"", e)
            finally:
                if connection:
                    cursor.close()
                    connection.close()
        except psycopg2.Error as e:
            logging.error(f""Error executing database query: {e}"")
            if isinstance(e, psycopg2.OperationalError) and ""could not connect to server"" in str(e):
                retry_count = 0
                while True:
                    time.sleep(1 << (retry_count + 1))
                    try:
                        connection = psycopg2.connect(**db_params)
                        cursor = connection.cursor()
                        cursor.execute(sql_query)
                        if ""commit"" in transaction_status_handler:
                            connection.commit()
                        elif ""rollback"" in transaction_status_handler:
                            connection.rollback()
                        else:
                            raise ValueError(""Invalid transaction status handler"")
                        break
                    except psycopg2.Error as e:
                        retry_count += 1
                        logging.error(f""Retrying database query after transient error: {e}"")
                        if retry_count >= 5:
                            raise DatabaseConnectionError(""Database connection timed out"", e)
                finally:
                    if connection:
                        cursor.close()
                        connection.close()
            else:
                raise']",0,[0],[],True,0,0,0,

