import csv
import io
import codecs
from typing import List, Tuple

def process_file(file_path: str, sorting_algorithm: str = 'quicksort', sequence_type: str = 'default', delimiter: str = '', encoding: str = 'utf-8') -> Tuple[int, List[str], List[List[str]]]:
    with codecs.open(file_path, 'r', encoding=encoding) as file:
        reader = csv.reader(io.StringIO(codecs.decode(file.read(), encoding)), delimiter=delimiter)
        lines = [line.strip() for line in reader]

    if sorting_algorithm == 'quicksort':
        sorted_lines = quicksort(lines)
    else:
        raise ValueError(""Unsupported sorting algorithm"")

    if sequence_type == 'reverse':
        sorted_lines.reverse()

    sub_sequences = []
    current_sub_sequence = []
    for line in sorted_lines:
        if delimiter and delimiter not in line:
            current_sub_sequence.append(line)
        elif current_sub_sequence:
            sub_sequences.append(current_sub_sequence)
            current_sub_sequence = [line]
    if current_sub_sequence:
        sub_sequences.append(current_sub_sequence)

    return len(lines), sorted_lines, sub_sequences

