def rsa_encrypt_decrypt(text_message, key, mode='encrypt'):
    if mode not in ['encrypt', 'decrypt']:
        raise ValueError(""Invalid mode. It should be either 'encrypt' or 'decrypt'"")

    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric import padding
    from cryptography.hazmat.backends import default_backend

    if mode == 'encrypt':
        encrypted_message = rsa_encrypt(key['public_key'], text_message)
    else:
        decrypted_message = rsa_decrypt(key['private_key'], text_message)

    return decrypted_message


def rsa_encrypt(public_key, text_message):
    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.backends import default_backend

    iv = os.urandom(16)  # Generate a fresh initialization vector for encryption
    encrypted_message = public_key.encrypt(
        text_message.encode('utf-8'), 
        padding.OAEP(
            mgf1=_hash.SHA256(),
            algorithm=serialization.Encoding.PKCS1v15(),
            label=None,
        )
    )

    return iv + encrypted_message


def rsa_decrypt(private_key, text_message):
    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.backends import default_backend

    if not isinstance(text_message, bytes):
        raise ValueError(""Input message should be a byte string"")

    iv = text_message[:16]  # Extract the initialization vector from the input message
    decrypted_message = private_key.decrypt(
        text_message[16:], 
        padding.OAEP(
            mgf1=_hash.SHA256(),
            algorithm=serialization.Encoding.PKCS1v15(),
            label=None,
        )
    )

    return iv + decrypted_message.decode('utf-8')


def generate_rsa_keys(key_size=2048):
    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.backends import default_backend

    private_key = serialization.generate_private_key(
        algorithm='RSA',
        key_size=key_size,
        backend=default_backend()
    )

    public_key = private_key.public_key()

    return {
        'private_key': private_key.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.Traditional,
            encryption_algorithm=serialization.NoEncryption(),
        ),
        'public_key': public_key.public_bytes(
            encoding=serialization.Encoding.OpenSSH,
            format=serialization.PublicFormat.Standard,
        )
    }


def authenticate_signature(private_key, signature):
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.backends import default_backend

    if not isinstance(signature, bytes):
        raise ValueError(""Signature should be a byte string"")

    try:
        private_key.verify(
            signature=signature,
            data=b'',
            padding=padding.PSS(
                mgf1=_hash.SHA256(),
                salt_length=padding.PSS.MAX_LENGTH
            ),
            algorithm=hashes.SHA256()
        )
        return True
    except Exception as e:
        print(f""Authentication failed: {str(e)}"")
        return False
