        self.employment_status = employment_status if employment_status else random.choice(['Full Time', 'Part Time'])

class JobTitle:
    def __init__(self, job_title=None, years_of_experience=None):
        self.job_title = job_title if job_title else random.choice(['Manager', 'Engineer', 'Analyst'])
        self.years_of_experience = years_of_experience if years_of_experience else random.randint(0, 20)

class EmployeeProfile:
    def __init__(self, employee_id=None, department=None, job_title=None):
        self.employee_id = employee_id if employee_id else generate_employee_id()
        self.department = department if department else Department(random.choice(['HR', 'Finance', 'IT']))
        self.job_title = job_title if job_title else JobTitle()

def generate_employee_id(seed):
    random.seed(seed)
    return str(random.randint(100000, 999999))

def populate_employees(num_employees=100, seed=123456789, callback=None):
    employees = []

    for _ in range(num_employees):
        department_name = random.choice(['HR', 'Finance', 'IT'])
        employment_status = EmploymentStatus()
        job_title = JobTitle()

        employee_profile = EmployeeProfile(generate_employee_id(seed), Department(department_name), job_title)

