python
import hashlib
import os

class CryptoFuncStruct:
    def __init__(self, name, func):
        self.name = name
        self.func = func

def get_available_crypto_functions():
    available_functions = []
    try:
        from cryptography.hazmat.primitives import hashes
        available_functions.append(CryptoFuncStruct(""SHA-256"", hashes.SHA256()))
    except ImportError:
        print(""SHA-256 unavailable"")

    try:
        from cryptography.hazmat.primitives import hashes
        available_functions.append(CryptoFuncStruct(""SHA-384"", hashes.SHA384()))
    except ImportError:
        print(""SHA-384 unavailable"")

    try:
        from cryptography.hazmat.primitives import hashes
        available_functions.append(CryptoFuncStruct(""SHA-512"", hashes.SHA512()))
    except ImportError:
        print(""SHA-512 unavailable"")

    return available_functions

def compute_md5(file_path):
    with open(file_path, ""rb"") as file:
        return hashlib.md5(file.read()).hexdigest()

def main():
    file_path = input(""Enter file path: "")

    if not os.path.exists(file_path):
        print(""File not found"")
        return

    metadata = {
        ""name"": os.path.basename(file_path),
        ""size"": os.path.getsize(file_path),
        ""last_modified"": os.path.getmtime(file_path)
    }

    print(""\nFile metadata:"")
    for key, value in metadata.items():
            print(f""{key}: {value}"")

    crypto_functions = get_available_crypto_functions()

    if not crypto_functions:
         return

    print(""\nAvailable Crypto Functions:"")
    for func in crypto_functions:
        print(func.name)

    choice = input(""Enter the name of a crypto function to compute hash (or 'MD5' for MD5 hash): "")

    if choice.lower() == ""md5"":
        file_hash = compute_md5(file_path)
        print(f""\nFile Hash: {file_hash}"")
    elif choice in [func.name for func in crypto_functions]:
        selected_func = next((func for func in crypto_functions if func.name == choice), None)

        if selected_func:
            try:
                from cryptography.hazmat.primitives import hashes
                file_hash = selected_func.func().digest().hex()
                print(f""\nFile Hash (using {choice}): {file_hash}"")
            except Exception as e:
                print(f""An error occurred: {e}"")
        else:
            print(""Invalid choice"")
    else:
        print(""Invalid choice"")

if __name__ == ""__main__"":
    main()
