import os
import hashlib
from Crypto.Cipher import AES, PKCS1_OAEP
from Crypto.PublicKey import RSA
from Crypto.Random import get_random_bytes

# Generate a random symmetric key for AES encryption
def generate_aes_key():
    return get_random_bytes(32)

# Encrypt a message using RSA asymmetric encryption
def encrypt_rsa(message, public_key):
    cipher_rsa = PKCS1_OAEP.new(public_key)
    return cipher_rsa.encrypt(message)

# Decrypt a message using RSA asymmetric decryption
def decrypt_rsa(ciphertext, private_key):
    cipher_rsa = PKCS1_OAEP.new(private_key)
    return cipher_rsa.decrypt(ciphertext)

# Encrypt a message using AES symmetric encryption and SHA-256 for integrity check with multiple recipients and signatures support 
def encrypt_aes_sha256(message, recipients_keys, signature_private_key):
    aes_keys = []

    for recipient in recipients_keys:
        aes_key = generate_aes_key()
        cipher = AES.new(aes_key, AES.MODE_EAX)
        ciphertext, tag = cipher.encrypt_and_digest(message.encode('utf-8'))

        # Hashing the ciphertext to ensure message integrity and add signature verification step
        hash_obj = hashlib.sha256()
        hash_obj.update(ciphertext)

        signatures = []

        for recipient_private in recipients_keys:
            if recipient_private != signature_private_key:
                signer = RSA.importKey(recipient_private)
                signer_cipher = signer.sign(hash_obj) # Sign the hash of the message with each recipient's private key.
                signatures.append(signer_cipher)

        # Combine all signatures and ciphertext with tags into a list of encrypted messages with associated keys and hashes for verification on decryption.
        aes_keys.append((aes_key.decode('utf-8'), (ciphertext, tag), hash_obj.hexdigest(), signatures))

    return aes_keys

# Decrypt an encrypted message using AES symmetric decryption with multiple recipients and verify SHA-256 hash along with signature checks  
def decrypt_aes_sha256(encrypted_message, aes_key):
    _, (ciphertext, tag), hash_val, signatures = encrypted_message

    # Hashing the decrypted data to verify integrity against pre-calculated value 
    decrypted_data_hash_obj = hashlib.sha256()

    deciphered_data_decoded = AES.new(aes_key.encode('utf-8'), AES.MODE_EAX).decrypt(ciphertext)

    if decrypted_data_hash_obj.update(deciphered_data_decoded) != hash_val.encode('utf-8'):
        raise Exception(""Decrypted data integrity check failed"")

    # Verify signatures for each recipient
    for i, (aes_key, message_parts, _, signature_list) in enumerate(encrypted_message):
        for j, signature in enumerate(signature_list):
            if not RSA.importKey(recipients_keys[i]).verify(hash_obj.digest(), signature):
                raise Exception(""Signature verification failed for recipient "" + str(j))

    return deciphered_data_decoded.decode('utf-8')
