```python
import base64
from Cryptodome.Cipher import AES, PKCS1_OAEP
from Cryptodome.Hash import SHA256, BLAKE2s
from Cryptodome.Random import get_random_bytes
from Cryptodome.Signature import PKCS1_PSS
from Cryptodome.Util.Padding import pad, unpad
import json
import os
import time
import bcrypt
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric.rsa import generate_private_key

class CryptoFunctions:
    def __init__(self):
        self.keys = {}

    def generate_key(self, key_size=256):
        key = get_random_bytes(key_size // 8)
        return base64.b64encode(key).decode()

    def hash_password(self, password, salt=None):
        if salt is None:
            salt = os.urandom(16)
        hashed_password = bcrypt.hashpw(password.encode(), salt + bcrypt.gensalt())
        return base64.b64encode(salt + hashed_password).decode()

    def verify_password(self, provided_password, stored_hashed_password):
        salt, hashed_password = base64.b64decode(stored_hashed_password).split(b'$')
        hashed_provided_password = bcrypt.hashpw(provided_password.encode(), salt + bcrypt.gensalt())
        return hashed_provided_password == base64.b64encode(hashed_password).decode()

    def encrypt_data(self, data, key):
        cipher = AES.new(base64.b64decode(key), AES.MODE_CBC, os.urandom(16))
        encrypted_data = pad(data.encode(), AES.block_size)
        return base64.b64encode(cipher.encrypt(encrypted_data)).decode()

    def decrypt_data(self, encrypted_data, key):
        cipher = AES.new(base64.b64decode(key), AES.MODE_CBC, os.urandom(16))
        decrypted_data = unpad(cipher.decrypt(base64.b64decode(encrypted_data)), AES.block_size).decode()
        return decrypted_data

    def generate_jwt_token(self, user_id):
        payload = {'user_id': user_id}
        return json.dumps(payload)

    def verify_jwt_token(self, token):
        try:
            return json.loads(token)
        except json.JSONDecodeError:
            return None

    def sign_message(self, message, private_key):
        signer = PKCS1_PSS.new(private_key)
        signature = signer.sign(message.encode())
        return base64.b64encode(signature).decode()

    def verify_signature(self, message, public_key, signature):
        verifier = PKCS1_PSS.new(public_key)
        try:
            verifier.verify(message.encode(), base64.b64decode(signature))
            return True
        except (ValueError, RuntimeError):
            return False

    def securely_delete_file(self, file_path):
        if os.path.exists(file_path):
            os.remove(file_path)

def main():
    crypto = CryptoFunctions()

    while True:
        print(""Select an operation:"")
        print(""1. Encrypt data"")
        print(""2. Decrypt data"")
        print(""3. Generate key"")
        print(""4. Verify password"")
        print(""5. Generate JWT token"")
        print(""6. Sign message"")
        print(""7. Verify signature"")
        print(""8. Securely delete file"")
        print(""9. Quit"")

        choice = input(""Enter your choice: "")

        if choice == '1':
            key = crypto.generate_key()
            data = input(""Enter the data to encrypt: "")
            encrypted_data = crypto.encrypt_data(data, key)
            print(f""Encrypted data: {encrypted_data}"")
        elif choice == '2':
            encrypted_data = input(""Enter the encrypted data: "")
            key = crypto.generate_key()
            decrypted_data = crypto.decrypt_data(encrypted_data, key)
            print(f""Decrypted data: {decrypted_data}"")
        elif choice == '3':
            key = crypto.generate_key()
            print(f""Generated key: {key}"")
        elif choice == '4':
            password = input(""Enter the password to verify: "")
            stored_hashed_password = input(""Enter the stored hashed password: "")
            if crypto.verify_password(password, stored_hashed_password):
                print(""Password verified"")
            else:
                print(""Invalid password"")
        elif choice == '5':
            user_id = int(input(""Enter the user ID: ""))
            token = crypto.generate_jwt_token(user_id)
            print(f""Generated JWT token: {token}"")
        elif choice == '6':
            message = input(""Enter the message to sign: "")
            private_key = generate_private_key()
            signature = crypto.sign_message(message, private_key)
            print(f""Signed message: {signature}"")
        elif choice == '7':
            message = input(""Enter the signed message: "")
            public_key = generate_private_key().public_key()
            if crypto.verify_signature(message, public_key, signature):
                print(""Signature verified"")
            else:
                print(""Invalid signature"")
        elif choice == '8':
            file_path = input(""Enter the file path to securely delete: "")
            crypto.securely_delete_file(file_path)
            print(f""File deleted: {file_path}"")
        elif choice == '9':
            break
        else:
            print(""Invalid choice. Please try again."")

