import json
from flask import Flask, request, jsonify
from flask_cors import cross_origin
from flask_jwt_extended import JWTManager, jwt_required, create_access_token
from datetime import datetime, timedelta

app = Flask(__name__)
app.config['SECRET_KEY'] = 'super-secret'
jwt = JWTManager(app)

class FileManager:
    def __init__(self):
        self.file_system = {}

    def get_file(self, file_path):
        if os.path.exists(file_path):
            return open(file_path, 'r').read()
        else:
            return None

    def set_file(self, file_path, content):
        with open(file_path, 'w') as f:
            f.write(content)

    def delete_file(self, file_path):
        try:
            os.remove(file_path)
        except FileNotFoundError:
            pass

    def create_file(self, file_path, content):
        with open(file_path, 'w') as f:
            f.write(content)

    def update_file(self, file_path, content):
        self.set_file(file_path, content)

@app.route('/file', methods=['GET', 'POST', 'PUT', 'DELETE'])
@cross_origin()
def file_operation():
    if request.method == 'GET':
        file_path = request.args.get('path')
        return json.dumps({'file': FileManager().get_file(file_path)})
    elif request.method == 'POST':
        file_path = request.form['path']
        content = request.files['content'].read().decode()
        FileManager().create_file(file_path, content)
        return jsonify({'message': 'File created successfully'})
    elif request.method == 'PUT':
        file_path = request.form['path']
        content = request.files['content'].read().decode()
        FileManager().update_file(file_path, content)
        return jsonify({'message': 'File updated successfully'})
    elif request.method == 'DELETE':
        file_path = request.args.get('path')
        FileManager().delete_file(file_path)
        return jsonify({'message': 'File deleted successfully'})

@app.route('/login', methods=['POST'])
@cross_origin()
def login():
    username = request.form['username']
    password = request.form['password']
    # authenticate user
    if authenticated:
        access_token = create_access_token(identity=username, expires_delta=timedelta(days=7))
        return jsonify({'access_token': access_token})
    else:
        return jsonify({'error': 'Invalid credentials'})

if __name__ == '__main__':
    app.run(debug=True)
