        raise ValueError(""Device blob must contain only strings"")

    if len(device_blob['product_id']) != 32:
        raise ValueError(""Product ID must be exactly 32 characters long"")

    return True

device_blobs = generate_device_blobs()

for i, device_blob in enumerate(device_blobs):
    try:
        validate_device_authentication(device_blob)
        print(f""Device {i+1} authenticated successfully with blob: {device_blob}"")
    except ValueError as e:
        print(f""Authentication failed for Device {i+1}: {e}"")
