class SecureMessage:
    def __init__(self, message_id: str, content: str, encryption_algorithm=""AES"", key_size=256):
        self.message_id = message_id
        self.content = content
        if not content:
            raise ValueError(""Content cannot be empty"")
        self.encryption_algorithm = encryption_algorithm
        self.key_size = key_size

    def encrypt(self, key: bytes) -> tuple:
        # Generate random nonce
        nonce = os.urandom(16)

        # Encrypt message content using chosen algorithm
        if self.encryption_algorithm == ""AES"":
            cipher_text = AES_encrypt(self.content.encode(), key, nonce)
        elif self.encryption_algorithm == ""ChaCha20"":
            cipher_text = ChaCha20_encrypt(self.content.encode(), key, nonce)
        else:
            raise ValueError(""Invalid encryption algorithm"")

        # Generate HMAC-SHA256 for integrity check
        hmac = hashlib.sha256(key + self.content.encode()).hexdigest()

        return cipher_text.decode(), nonce.hex(), hmac

    def verify_integrity(self, encrypted_content: str, key: bytes) -> bool:
        if not encrypted_content or not key:
            raise ValueError(""Invalid input"")

        # Decrypt and compare with original content
        decrypted_content = decrypt(encrypted_content, key)
        return decrypted_content == self.content.encode().decode()


class SecureMessageManager:
    def __init__(self):
        self.key_repository = {}
        self.logger = logging.getLogger(__name__)

    def create_message(self, message_id: str, content: str) -> SecureMessage:
        if not message_id or not content:
            raise ValueError(""Invalid input"")

        key = generate_key()
        message = SecureMessage(message_id, content)
        encrypted_content, nonce, hmac = message.encrypt(key)

        self.key_repository[message_id] = {""key"": key, ""nonce"": nonce}
        self.logger.info(f""Created message {message_id} with encryption status: success"")

        return message

    def retrieve_message(self, message_id: str) -> tuple:
        if not message_id or message_id not in self.key_repository:
            raise ValueError(""Invalid message ID"")

        key = self.key_repository[message_id][""key""]
        nonce = self.key_repository[message_id][""nonce""]

        # Retrieve and decrypt the encrypted message
        encrypted_content = retrieve_encrypted_message(message_id)
        decrypted_content, _, _ = encrypt(encrypted_content, key)

        return decrypted_content.decode(), key, nonce

    def verify_message(self, message_id: str) -> bool:
        if not message_id or message_id not in self.key_repository:
            raise ValueError(""Invalid message ID"")

        content, key, nonce = self.retrieve_message(message_id)
        return self.verify_integrity(content, key)


