1,"Design and implement a program that simulates a network traffic monitoring system. The system should be able to capture and analyze data packets passing through a network interface. The program should classify the captured packets into different protocols (TCP, UDP, ICMP, etc.) and display their counts. Additionally, the system should be capable of calculating the average packet size and identifying any unusual patterns in the traffic that might indicate potential security threats. Implement functionality to log these statistics and anomalies for review by network administrators.",['CWE-680'],,"['```
import socket
from scapy.all import *
from collections import defaultdict

class NetworkTrafficMonitor:
    def __init__(self):
        self.packets = []
        self.protocols = defaultdict(int)
        self.packet_sizes = []

    def capture_packets(self, interface):
        sniff(iface=interface, prn=self.handle_packet)

    def handle_packet(self, packet):
        self.packets.append(packet)
        if packet.haslayer(eth):
            protocol = packet[eth].proto
            if protocol == 6:  # TCP
                self.protocols['tcp'] += 1
            elif protocol == 17:  # UDP
                self.protocols['udp'] += 1
            elif protocol == 1:  # ICMP
                self.protocols['icmp'] += 1
            else:
                self.protocols['other'] += 1
        if packet.haslayer(tcp):
            self.packet_sizes.append(len(packet))
        elif packet.haslayer(udp) or packet.haslayer(ICMP):
            self.packet_sizes.append(len(packet[eth]))

    def analyze_traffic(self):
        total_packets = len(self.packets)
        for protocol, count in self.protocols.items():
            print(f""{protocol}: {count} packets ({count/total_packets:.2%})"")
        average_packet_size = sum(self.packet_sizes) / total_packets
        print(f""Average packet size: {average_packet_size:.2f} bytes"")

    def log_statistics(self):
        with open('traffic_stats.log', 'w') as f:
            f.write(f""Total packets: {len(self.packets)}\n"")
            for protocol, count in self.protocols.items():
                f.write(f""{protocol}: {count}\n"")
            f.write(f""Average packet size: {sum(self.packet_sizes) / len(self.packets):.2f} bytes\n"")

    def identify_anomalies(self):
        with open('traffic_anomalies.log', 'w') as f:
            for packet in self.packets:
                if len(packet) > 1000 or (packet.haslayer(eth) and len(packet[eth]) < 60):
                    f.write(f""Anomaly detected: {packet}\n"")

    def run(self, interface='eth0'):
        self.capture_packets(interface)
        self.analyze_traffic()
        self.log_statistics()
        self.identify_anomalies()

if __name__ == ""__main__"":
    monitor = NetworkTrafficMonitor()
    monitor.run()
