        self.books = {}
        self.book_id_counter = 0

    def add_book(self, author, title, isbn):
        book_id = f""book_{self.book_id_counter}""
        self.book_id_counter += 1
        self.books[book_id] = BookSyncData(author, title, isbn)

    def update_book(self, book_id, author=None, title=None, isbn=None):
        if book_id in self.books:
            if author: self.books[book_id].author = author
            if title: self.books[book_id].title = title
            if isbn: self.books[book_id].isbn = isbn

    def remove_book(self, book_id):
        if book_id in self.books:
            del self.books[book_id]

    def generate_sync_data_array(self):
        sync_data = []
        for book_id, book in self.books.items():
            book_info = {
                ""book_id"": book_id,
                ""author"": book.author,
                ""title"": book.title,
                ""isbn"": book.isbn,
                ""synchronization_status"": book.synchronization_status
            }
            if random.randint(0, 1):
                book_info[""synchronization_status""] = ""out_of_sync""
            sync_data.append(BookSyncData(**book_info))
        return sync_data

library_db = LibraryDatabase()

# Example usage:
library_db.add_book(""John Smith"", ""The Great Gatsby"", ""9780743273565"")
library_db.add_book(""Jane Doe"", ""To Kill a Mockingbird"", ""9780446310789"")

print(library_db.generate_sync_data_array())
