class CustomSet:
    def __init__(self):
        self.data = set()

    def add(self, element):
        self.data.add(element)

    def remove(self, element):
        if element in self.data:
            self.data.remove(element)
        else:
            print(""Element not found"")

    def contains(self, element):
        return element in self.data

    def union(self, other_set):
        return CustomSet({*self.data, *other_set.data})

    def intersection(self, other_set):
        return CustomSet({element for element in self.data if element in other_set.data})

    def difference(self, other_set):
        return CustomSet({element for element in self.data if element not in other_set.data})

    def symmetric_difference(self, other_set):
        return CustomSet({*self.data, *other_set.data}) - (self.intersection(other_set))


def sort_tuples(tuples_list, criteria_list):
