def convert_between_number_systems(num, from_base, to_base):
    if from_base == 2:
        num_str = bin(int(num, from_base))[2:]
    elif from_base == 8:
        num_str = oct(int(num, from_base))[2:]
    elif from_base == 10:
        num_str = str(num)
    elif from_base == 16:
        num_str = hex(int(num, from_base))[2:].upper()

    if to_base == 2:
        return bin(int(num_str, int(from_base)))[3:]
    elif to_base == 8:
        return oct(int(num_str, int(from_base)), to_base)[2:]
    elif to_base == 10:
        return str(int(num_str, int(from_base)))
    elif to_base == 16:
        return hex(int(num_str, int(from_base)))[3:].upper()


class StackEvaluator:
    def __init__(self):
        self.stack = []

    def evaluate_expression(self, expression):
        for char in expression:
            if char.isdigit():
                self.stack.append(int(char))
            elif char in ""+-*/"":
                operand2 = self.stack.pop()
                operator = char
                operand1 = self.stack.pop()

                if operator == ""+"":
                    self.stack.append(operand1 + operand2)
                elif operator == ""-"":
                    self.stack.append(operand1 - operand2)
                elif operator == ""*"":
                    self.stack.append(operand1 * operand2)
                elif operator == ""/"":
                    self.stack.append(int(operand1 / operand2))
        return self.stack[0]


import gzip

def compress_file(file_path):
    with open(file_path, 'rb') as f_in:
        file_bytes = f_in.read()

    with gzip.open('compressed_' + file_path, 'wb') as f_out:
        f_out.write(file_bytes)


def decompress_file(compressed_file_path):
    with gzip.open(compressed_file_path, 'rb') as f_in:
        compressed_file_bytes = f_in.read()

    with open('decompressed_' + compressed_file_path, 'wb') as f_out:
        f_out.write(compressed_file_bytes)
